import { describe, expect, it } from 'vitest'
import {
	checksum,
	connect,
	connectOnGo,
	databaseChecksumRequest,
	dualControllerStatusRequest,
	endsMerging,
	fromWire,
	go,
	GoMode,
	interrogate,
	isAddress,
	mergeKey,
	routerConfigurationRequest,
	toWireAddress,
} from '../api/index.js'

/**
 * Every message below is byte for byte what the 1.2.4 JavaScript module built for the same arguments: they were
 * generated by running its calcDivMod / calcCheckSum before it was replaced. There is no device capture, but those bytes
 * are what routers have been receiving, so the encoder must not drift from them.
 */
describe('message encoding matches the 1.2.4 module', () => {
	it.each([
		[1, [0xff, 0x01, 0x00, 0x00, 0x7f]],
		[128, [0xff, 0x01, 0x00, 0x7f, 0x00]],
		[129, [0xff, 0x01, 0x10, 0x00, 0x6f]],
		[200, [0xff, 0x01, 0x10, 0x47, 0x28]],
		[1024, [0xff, 0x01, 0x70, 0x7f, 0x10]],
	])('interrogate destination %i', (destination, bytes) => {
		expect([...interrogate(destination)]).toEqual(bytes)
	})

	it.each([
		[1, 1, [0xff, 0x02, 0x00, 0x00, 0x00, 0x7e]],
		[128, 129, [0xff, 0x02, 0x01, 0x7f, 0x00, 0x7e]],
		[200, 1000, [0xff, 0x02, 0x17, 0x47, 0x67, 0x39]],
		[1024, 1024, [0xff, 0x02, 0x77, 0x7f, 0x7f, 0x09]],
		[5, 3, [0xff, 0x02, 0x00, 0x04, 0x02, 0x78]],
	])('connect destination %i source %i', (destination, source, bytes) => {
		expect([...connect(destination, source)]).toEqual(bytes)
	})

	it.each([
		[1, 1, [0xff, 0x05, 0x00, 0x00, 0x00, 0x7b]],
		[200, 1000, [0xff, 0x05, 0x17, 0x47, 0x67, 0x36]],
	])('connect on go destination %i source %i', (destination, source, bytes) => {
		expect([...connectOnGo(destination, source)]).toEqual(bytes)
	})

	it('go set and clear', () => {
		expect([...go(GoMode.Set)]).toEqual([0xff, 0x06, 0x00, 0x7a])
		expect([...go(GoMode.Clear)]).toEqual([0xff, 0x06, 0x01, 0x79])
	})

	it('the queries made on connecting', () => {
		expect([...databaseChecksumRequest()]).toEqual([0xff, 0x00, 0x00, 0x00])
		expect([...dualControllerStatusRequest()]).toEqual([0xff, 0x32, 0x4e])
		expect([...routerConfigurationRequest()]).toEqual([0xff, 0x4b, 0x35])
	})
})

describe('checksum', () => {
	it('makes everything after SOM sum to a multiple of 128', () => {
		for (const body of [[0x02, 0x17, 0x47, 0x67], [0x00, 0x00], [0x7f, 0x7f, 0x7f], [0x4b]]) {
			const sum = [...body, checksum(body)].reduce((a, b) => a + b, 0)
			expect(sum % 128).toBe(0)
			expect(checksum(body)).toBeLessThan(128)
		}
	})
})

describe('addresses', () => {
	it('accepts whole numbers from 1 to 1024 only', () => {
		expect([1, 512, 1024].every(isAddress)).toBe(true)
		expect([0, -1, 1025, 1.5, Number.NaN, '5', undefined].some(isAddress)).toBe(false)
	})

	it('refuses to build a message for an address the commands cannot carry', () => {
		expect(() => toWireAddress(0)).toThrow(RangeError)
		expect(() => toWireAddress(1025)).toThrow(RangeError)
		expect(() => connect(1, 2.5)).toThrow(RangeError)
		expect(() => interrogate(Number.NaN)).toThrow(RangeError)
	})

	it('round trips every address through the wire form', () => {
		for (let destination = 1; destination <= 1024; destination += 37) {
			const source = 1025 - destination
			const msg = connect(destination, source)
			expect(fromWire(msg[2], msg[3], msg[4])).toEqual({ destination, source })
		}
	})

	it('reads addresses as the 1.2.4 module did', () => {
		// returnDstSrc(multiplier, dst, src) from 1.2.4, for the same bytes
		expect(fromWire(0x00, 4, 2)).toEqual({ destination: 5, source: 3 })
		expect(fromWire(0x17, 71, 103)).toEqual({ destination: 200, source: 1000 })
		expect(fromWire(0x77, 127, 127)).toEqual({ destination: 1024, source: 1024 })
	})

	it('ignores multiplier bit 3, which 1.2.4 read as half a destination multiplier', () => {
		// 1.2.4 computed (multiplier - (multiplier & 7)) / 16, so 0x08 gave destination 65 rather than 1
		expect(fromWire(0x08, 0, 0)).toEqual({ destination: 1, source: 1 })
		expect(fromWire(0x1f, 71, 103)).toEqual({ destination: 200, source: 1000 })
	})
})

describe('merging', () => {
	it('gives every interrogate of a destination one key, and every connect to one another', () => {
		expect(mergeKey(interrogate(200))).toBe(mergeKey(interrogate(200)))
		// Source 1000 sets the multiplier's low bits, which are not the destination's
		expect(mergeKey(connect(200, 1))).toBe(mergeKey(connect(200, 1000)))
		expect(mergeKey(interrogate(200))).not.toBe(mergeKey(connect(200, 1)))
	})

	it('keys each destination apart, high bits included', () => {
		// 1, 129 and 257 differ only in their DIV 128
		const keys = [1, 129, 257, 200, 1024].flatMap((d) => [mergeKey(interrogate(d)), mergeKey(connect(d, 1))])
		expect(keys).not.toContain(undefined)
		expect(new Set(keys).size).toBe(keys.length)
	})

	it('never merges anything else', () => {
		const others = [
			connectOnGo(5, 1),
			go(GoMode.Set),
			databaseChecksumRequest(),
			dualControllerStatusRequest(),
			routerConfigurationRequest(),
		]
		for (const message of others) expect(mergeKey(message)).toBeUndefined()
	})

	it('stops merging at a GO, and only at a GO', () => {
		expect(endsMerging(go(GoMode.Set))).toBe(true)
		expect(endsMerging(go(GoMode.Clear))).toBe(true)
		for (const message of [interrogate(5), connect(5, 1), connectOnGo(5, 1), databaseChecksumRequest()]) {
			expect(endsMerging(message)).toBe(false)
		}
	})
})
